    var text = String(body || '');
    var start = text.indexOf(prefix);
    if (start === -1) return null;
    start += prefix.length;
    var end = text.indexOf(suffix, start);
    if (end === -1) return null;
    var parsed;
    try { parsed = JSON.parse(text.substring(start, end).trim()); } catch (e) { return null; }
